import { TaskComponent } from './components/task/task.component';
import { TaskSettingsComponent } from './components/task/task-settings/task-settings.component';

const routes: Routes = [
	{
		path: 'dashboard',
		component: TaskComponent
	},
	{
		path: 'team',
		component: TaskComponent
	},
	{
		path: 'me',
		component: TaskComponent
	},
	{
		path: 'settings/:id',
		component: TaskSettingsComponent
	}
];

@NgModule({
