	ITimeSlot,
	IGoal,
	ICandidate,
	IEmployeeAward
} from '@gauzy/contracts';
import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { ColumnNumericTransformerPipe } from './../shared/pipes';
import {
	Column,
	Entity,
	JoinColumn,
	JoinTable,
